<form method="post" action="/workspace/settings">@csrf<div class="columns"><section class="panel"><h2>Account</h2><h3>{{auth()->user()->name}}</h3><p class="muted">{{ucwords(str_replace('_',' ',auth()->user()->role))}}</p><p>{{auth()->user()->email}}</p><button type="button" class="outline" data-dialog="change-password">Change Password</button><h3>System Preferences</h3><div class="form-grid"><label class="field">Theme<select name="theme">@foreach(['Light','Dark'] as $theme)<option @selected((auth()->user()->preferences['theme']??'Light')===$theme)>{{$theme}}</option>@endforeach</select></label><label class="field">Date Format<select name="date_format">@foreach(['mm/dd/yyyy','dd/mm/yyyy'] as $format)<option @selected((auth()->user()->preferences['date_format']??'mm/dd/yyyy')===$format)>{{$format}}</option>@endforeach</select></label><label class="field">Time Format<select name="time_format"><option value="12" @selected((auth()->user()->preferences['time_format']??'12')==='12')>12-Hour (AM/PM)</option><option value="24" @selected((auth()->user()->preferences['time_format']??'12')==='24')>24-Hour</option></select></label></div><div class="actions"><button>Save Unit Defaults</button></div></section><section class="panel"><h2>Notifications</h2>@php($alertLabels=auth()->user()->role==='admin'?['submissions'=>'Reports Forwarded by Assistant','resubmitted'=>'Resubmitted Reports','feedback'=>'Assistant Replies','overdue'=>'Overdue Admin Reviews']:(auth()->user()->role==='assistant'?['submissions'=>'New Unit Report Submissions','resubmitted'=>'Resubmitted Reports','feedback'=>'Unit Head Replies','overdue'=>'Overdue Review Reminders']:['submissions'=>'New Transaction Submissions','resubmitted'=>'Requirements Resubmitted','feedback'=>'Assistant / Admin Feedback']))
