<div class="security"><span>In-App Transaction & Report Updates</span><input class="toggle" type="checkbox" aria-label="In-app notifications" name="in_app" value="1" @checked(auth()->user()->preferences['in_app']??true)></div><div class="security"><span>Email Notifications</span><input class="toggle" type="checkbox" aria-label="Email notifications" name="email" value="1" @checked(auth()->user()->preferences['email']??false)></div><h3>Data Backup & Security</h3><div class="security"><span>Backup Data</span><a class="button outline" href="/workspace/backup">Backup Now</a></div><div class="security"><span>Two-step verification</span><input class="toggle" type="checkbox" aria-label="Two-step verification" name="two_factor" value="1" @checked(auth()->user()->two_factor)></div><p class="muted">Sign-in codes use the configured email delivery service.</p><button type="button" class="outline" data-dialog="login-activity">View Login Activity</button><div class="actions"><button>Save Changes</button><a class="button quiet" href="/workspace/settings">Cancel</a></div></section></div>
